const SECONDS = { d: 86400, h: 3600, m: 60, s: 1 } as const;
const input = text.trim();
if (!/^(\d+[dhms]\s*)+$/.test(input)) {
  throw new Error(`invalid duration: "${text}"`);
}
let total = 0;
for (const [, amount, unit] of input.matchAll(/(\d+)([dhms])/g)) {
  total += Number(amount) * SECONDS[unit as keyof typeof SECONDS];
}
return total;

